(function(root){'use strict';const allowed=[1,1.5,2,3],key='grand-journey-combat-speed';function normalize(n){return allowed.includes(+n)?+n:1;}function read(storage){try{return normalize((storage||root.localStorage).getItem(key));}catch{return 1;}}function write(n,storage){const value=normalize(n);try{(storage||root.localStorage).setItem(key,String(value));}catch{}return value;}root.CombatSpeed={allowed,normalize,read,write};if(typeof module!=='undefined')module.exports=root.CombatSpeed;})(typeof globalThis!=='undefined'?globalThis:this);
